# Throwaway profiling notebook (read-only): plan time vs run time of the heavy notebook_01 cells, scoped to 3 files.
import time
spark.createDataFrame([(f,) for f in ['1mbB6-42clv2ZmQxs2pzubRFhP544RPKd', '1fMbj2uNDqmmktvJEKI_J7GSxSkxen6sn', '19aXyh-umRY7ly2Ne_evnMvHzeLLB0tSZ']], "file_id string").createOrReplaceTempView("tmp_scope")
CELLS = {'5e': '-- Cell 5e — Household member inference from silver_transcript_person_mention (v2)\n\n\nWITH\n\n-- Files already matched to a primary person, with that document\'s year\n-- Restricted to the TRUE primary match only (Cell 5/5b/5c\'s own methods).\n-- Bug found live this session: without this filter, once Cell 5g/5h/5f have\n-- written their own inferred rows to silver_document_person, a later cell\n-- re-deriving matched_docs from the same table picks those rows up as if\n-- they were additional "primaries" too -- e.g. after Cell 5g matched Clara\n-- as Executor (SPOUSE relation) on Charles Edward Ball\'s 1934 will, Cell 5h\n-- treated CLARA as a second primary and computed her own SIBLING (Samuel\n-- Mattock) as if he were related to Charles Edward Ball directly -- silently\n-- causing Cell 5h to skip its whole-tree fallback for him, thinking Cell 5g\n-- had already covered it. Excluding this session\'s two new match_methods\n-- keeps every cell\'s candidate pool anchored to the one true primary.\nmatched_docs AS (\n  SELECT sdp.file_id, sdp.person_gedcom_id AS primary_person_id, ot.year, ot.file_name\n  FROM genealogy.silver_document_person sdp\n  JOIN genealogy.ocr_transcriptions ot ON ot.file_id = sdp.file_id\n  WHERE sdp.file_id IN (SELECT DISTINCT file_id FROM genealogy.silver_transcript_person_mention)\n    AND sdp.file_id IN (SELECT file_id FROM tmp_scope)\n    AND sdp.match_method NOT IN (\'HOUSEHOLD_INFERENCE_V2\', \'WHOLE_TREE_NAME_MATCH\', \'MENTION_OVERRIDE\')\n  GROUP BY sdp.file_id, sdp.person_gedcom_id, ot.year, ot.file_name\n),\n\n-- Person-mention rows in scope for this pass: household roles only (see\n-- Cell 5e markdown for why Will/Probate roles are deliberately excluded).\n-- role_in_record maps to the same SPOUSE/CHILD/PARENT vocabulary\n-- silver_family/silver_family_child queries use elsewhere in this notebook.\nmentions AS (\n  SELECT tpm.file_id, tpm.page_index, tpm.person_index, tpm.name_raw, tpm.age_years, tpm.dob_raw,\n    ot2.doc_type_detected AS doc_type,\n    COALESCE((SELECT MAX(ab.full_name) FROM genealogy.ref_forename_abbreviation ab WHERE ab.abbr = UPPER(TRIM(REGEXP_EXTRACT(tpm.name_raw, \'^(\\\\S+)\', 1)))), UPPER(TRIM(REGEXP_EXTRACT(tpm.name_raw, \'^(\\\\S+)\', 1)))) AS forename_first,\n    UPPER(TRIM(REGEXP_EXTRACT(tpm.name_raw, \'(\\\\S+)$\', 1))) AS surname_last,\n    CASE\n      WHEN tpm.role_in_record IN (\'Wife\', \'Husband\') THEN \'SPOUSE\'\n      WHEN tpm.role_in_record IN (\'Son\', \'Daughter\', \'Child\') THEN \'CHILD\'\n    END AS mapped_relation,\n    -- dob_raw is a full transcribed date (e.g. "29 Dec 1903") -- the 1939\n    -- Register records exact DOB instead of age, so this is the only\n    -- birth-year signal available for those rows.\n    TRY_CAST(REGEXP_EXTRACT(tpm.dob_raw, \'(\\\\d{4})$\', 1) AS INT) AS dob_year\n  FROM genealogy.silver_transcript_person_mention tpm\n  JOIN (SELECT DISTINCT file_id, doc_type_detected FROM genealogy.ocr_transcriptions) ot2\n    ON ot2.file_id = tpm.file_id\n  WHERE tpm.role_in_record IN (\'Wife\', \'Husband\', \'Son\', \'Daughter\', \'Child\')\n    AND tpm.override_person_gedcom_id IS NULL\n    -- Scope the mention scan itself: filtering matched_docs alone left these scans (and their per-row\n    -- abbreviation lookups) running over every mention in the corpus.\n    AND tpm.file_id IN (SELECT file_id FROM tmp_scope)\n    -- Cell 5f role-expansion brief: Cell 5b\'s marriage-certificate spouse\n    -- inference is structurally unambiguous (the second party comes straight\n    -- from silver_family, no OCR dependency) and more reliable than reading a\n    -- name off the document for that one doc type -- running both risks\n    -- duplicate/conflicting rows. Scoped to MarriageCertificate + Spouse only;\n    -- every other doc type\'s spouse matching here is unaffected.\n    AND NOT (tpm.role_in_record IN (\'Wife\', \'Husband\') AND ot2.doc_type_detected = \'MarriageCertificate\')\n),\n\n-- Structurally known relatives of the matched primary person: spouse,\n-- children, parents. Same three-way pattern used elsewhere in this notebook.\nrelatives AS (\n  SELECT md.file_id, md.year, md.primary_person_id,\n    CASE WHEN sf.husband_gedcom_id = md.primary_person_id THEN sf.wife_gedcom_id ELSE sf.husband_gedcom_id END AS relative_id,\n    \'SPOUSE\' AS relation\n  FROM matched_docs md\n  JOIN genealogy.silver_family sf\n    ON sf.husband_gedcom_id = md.primary_person_id OR sf.wife_gedcom_id = md.primary_person_id\n  WHERE sf.relationship_type IS NULL\n\n  UNION ALL\n\n  SELECT md.file_id, md.year, md.primary_person_id, fc.child_gedcom_id AS relative_id, \'CHILD\' AS relation\n  FROM matched_docs md\n  JOIN genealogy.silver_family sf\n    ON sf.husband_gedcom_id = md.primary_person_id OR sf.wife_gedcom_id = md.primary_person_id\n  JOIN genealogy.silver_family_child fc ON fc.family_gedcom_id = sf.family_gedcom_id\n),\n\nrelatives_named AS (\n  SELECT DISTINCT r.file_id, r.year, r.relation, r.relative_id,\n    COALESCE(pl.given_name, \'\') AS given_name, COALESCE(pl.surname, \'\') AS surname,\n    pl.birth_year, pl.death_year\n  FROM relatives r\n  JOIN genealogy.gold_person_life pl ON pl.person_gedcom_id = r.relative_id\n  WHERE r.relative_id IS NOT NULL AND r.relative_id != r.primary_person_id\n),\n\n-- A relative\'s own tree name plus any alias (MARRIED_NAME etc.) both get a\n-- chance to match -- needed e.g. for a wife recorded under her married\n-- surname rather than the tree\'s maiden-name row.\ncandidate_names AS (\n  SELECT file_id, year, relation, relative_id, birth_year, death_year,\n    COALESCE((SELECT MAX(ab.full_name) FROM genealogy.ref_forename_abbreviation ab WHERE ab.abbr = UPPER(TRIM(REGEXP_EXTRACT(given_name, \'^(\\\\S+)\', 1)))), UPPER(TRIM(REGEXP_EXTRACT(given_name, \'^(\\\\S+)\', 1)))) AS forename_first, UPPER(TRIM(surname)) AS surname\n  FROM relatives_named\n  WHERE surname != \'\'\n\n  UNION ALL\n\n  SELECT rn.file_id, rn.year, rn.relation, rn.relative_id, rn.birth_year, rn.death_year,\n    COALESCE((SELECT MAX(ab.full_name) FROM genealogy.ref_forename_abbreviation ab WHERE ab.abbr = UPPER(TRIM(REGEXP_EXTRACT(a.alias_given_name, \'^(\\\\S+)\', 1)))), UPPER(TRIM(REGEXP_EXTRACT(a.alias_given_name, \'^(\\\\S+)\', 1)))) AS forename_first, UPPER(TRIM(a.alias_surname)) AS surname\n  FROM relatives_named rn\n  JOIN genealogy.silver_person_alias a ON a.person_gedcom_id = rn.relative_id\n  WHERE a.alias_surname IS NOT NULL AND a.alias_surname != \'\'\n),\n\n-- A candidate matches a mention only within its own role-mapped pool (a\n-- Wife mention never checked against CHILD candidates), and only if alive\n-- at the document\'s year -- a loose plausibility gate, not an age match;\n-- see Cell 5e markdown for why a tight age tolerance rejected genuine\n-- matches during validation.\ncandidate_matches AS (\n  SELECT DISTINCT c.file_id, c.relation, c.relative_id, c.birth_year,\n    m.page_index, m.person_index, m.name_raw,\n    CASE\n      WHEN m.age_years IS NOT NULL THEN TRY_CAST(SUBSTR(c.year, 1, 4) AS INT) - m.age_years\n      WHEN m.dob_year IS NOT NULL THEN m.dob_year\n    END AS implied_birth_year\n  FROM candidate_names c\n  JOIN mentions m\n    ON m.file_id = c.file_id\n   AND m.mapped_relation = c.relation\n   AND m.forename_first = c.forename_first\n   AND m.surname_last = c.surname\n  WHERE c.birth_year <= TRY_CAST(SUBSTR(c.year, 1, 4) AS INT)\n    AND (c.death_year IS NULL OR c.death_year >= TRY_CAST(SUBSTR(c.year, 1, 4) AS INT))\n    -- Census age gate (same rule as Cell 5h2 and notebook_02): a census age is a true age\n    -- at the document date, so a mention more than 5 years from the candidate\'s tree birth\n    -- year is not that candidate. Applies to single-candidate matches too, so a grandchild\n    -- sharing a name with a known child is not linked as the child.\n    AND NOT (m.doc_type = \'Census\' AND m.age_years IS NOT NULL AND c.birth_year IS NOT NULL\n             AND ABS(TRY_CAST(SUBSTR(c.year, 1, 4) AS INT) - m.age_years - c.birth_year) > 5)\n),\n\n-- How many distinct candidates matched each specific mention -- a genuine\n-- same-forename-same-role sibling collision (not hit in the validated test\n-- corpus, but structurally possible) needs the age/DOB tie-break below;\n-- an unambiguous mention (the common case) doesn\'t.\nmention_candidate_counts AS (\n  SELECT file_id, page_index, person_index, COUNT(DISTINCT relative_id) AS n_candidates\n  FROM candidate_matches\n  GROUP BY file_id, page_index, person_index\n),\n\nranked AS (\n  SELECT cm.*, mcc.n_candidates,\n    ROW_NUMBER() OVER (\n      PARTITION BY cm.file_id, cm.page_index, cm.person_index\n      ORDER BY ABS(COALESCE(cm.implied_birth_year, cm.birth_year) - cm.birth_year) ASC, cm.relative_id ASC\n    ) AS rk\n  FROM candidate_matches cm\n  JOIN mention_candidate_counts mcc ON mcc.file_id = cm.file_id AND mcc.page_index <=> cm.page_index AND mcc.person_index = cm.person_index\n),\n\n-- Collapse to one row per (file, relative) -- a person mentioned more than\n-- once in the same document (not seen in the test corpus) would otherwise\n-- fan out.\nfinal AS (\n  -- MIN over the (page_index, person_index) struct keeps the pair from one mention.\n  SELECT file_id, relative_id, relation,\n    MIN(STRUCT(page_index, person_index)).page_index AS page_index,\n    MIN(STRUCT(page_index, person_index)).person_index AS person_index\n  FROM ranked\n  WHERE n_candidates = 1 OR rk = 1\n  GROUP BY file_id, relative_id, relation\n)\n\nSELECT\n  f.file_id,\n  md.file_name,\n  f.relative_id AS person_gedcom_id,\n  pl.given_name || \' \' || pl.surname AS display_name,\n  \'HOUSEHOLD_INFERENCE_V2\' AS match_method,\n  \'MEDIUM\' AS match_confidence,\n  1 AS candidate_count,\n  CONCAT(\'Household member (\', f.relation, \') matched via silver_transcript_person_mention\') AS notes,\n  CURRENT_TIMESTAMP(),\n  f.page_index,\n  f.person_index\nFROM final f\nJOIN matched_docs md ON md.file_id = f.file_id\nJOIN genealogy.gold_person_life pl ON pl.person_gedcom_id = f.relative_id\nWHERE NOT EXISTS (\n  SELECT 1 FROM genealogy.silver_document_person sdp\n  WHERE sdp.file_id = f.file_id AND sdp.person_gedcom_id = f.relative_id\n)', '5f': '-- Cell 5f — Tier 1 role expansion: Parent (fixed), Grandparent, Sibling, Grandchild\n\n\nWITH\n\n-- Restricted to the TRUE primary match only (Cell 5/5b/5c\'s own methods).\n-- Bug found live this session: without this filter, once Cell 5g/5h/5f have\n-- written their own inferred rows to silver_document_person, a later cell\n-- re-deriving matched_docs from the same table picks those rows up as if\n-- they were additional "primaries" too -- e.g. after Cell 5g matched Clara\n-- as Executor (SPOUSE relation) on Charles Edward Ball\'s 1934 will, Cell 5h\n-- treated CLARA as a second primary and computed her own SIBLING (Samuel\n-- Mattock) as if he were related to Charles Edward Ball directly -- silently\n-- causing Cell 5h to skip its whole-tree fallback for him, thinking Cell 5g\n-- had already covered it. Excluding this session\'s two new match_methods\n-- keeps every cell\'s candidate pool anchored to the one true primary.\nmatched_docs AS (\n  SELECT sdp.file_id, sdp.person_gedcom_id AS primary_person_id, ot.year, ot.file_name\n  FROM genealogy.silver_document_person sdp\n  JOIN genealogy.ocr_transcriptions ot ON ot.file_id = sdp.file_id\n  WHERE sdp.file_id IN (SELECT DISTINCT file_id FROM genealogy.silver_transcript_person_mention)\n    AND sdp.file_id IN (SELECT file_id FROM tmp_scope)\n    AND sdp.match_method NOT IN (\'HOUSEHOLD_INFERENCE_V2\', \'WHOLE_TREE_NAME_MATCH\', \'MENTION_OVERRIDE\')\n  GROUP BY sdp.file_id, sdp.person_gedcom_id, ot.year, ot.file_name\n),\n\nmentions AS (\n  SELECT tpm.file_id, tpm.person_index, tpm.name_raw, tpm.age_years, tpm.dob_raw,\n    (SELECT MAX(o.doc_type_detected) FROM genealogy.ocr_transcriptions o WHERE o.file_id = tpm.file_id) AS doc_type,\n    COALESCE((SELECT MAX(ab.full_name) FROM genealogy.ref_forename_abbreviation ab WHERE ab.abbr = UPPER(TRIM(REGEXP_EXTRACT(tpm.name_raw, \'^(\\\\S+)\', 1)))), UPPER(TRIM(REGEXP_EXTRACT(tpm.name_raw, \'^(\\\\S+)\', 1)))) AS forename_first,\n    UPPER(TRIM(REGEXP_EXTRACT(tpm.name_raw, \'(\\\\S+)$\', 1))) AS surname_last,\n    CASE\n      WHEN tpm.role_in_record IN (\'Father\', \'Mother\') THEN \'PARENT\'\n      WHEN tpm.role_in_record IN (\'Grandfather\', \'Grandmother\') THEN \'GRANDPARENT\'\n      WHEN tpm.role_in_record IN (\'Brother\', \'Sister\') THEN \'SIBLING\'\n      WHEN tpm.role_in_record IN (\'Grandson\', \'Granddaughter\', \'Grandchild\', \'Grand Son\', \'Grand Daughter\') THEN \'GRANDCHILD\'\n    END AS mapped_relation,\n    TRY_CAST(REGEXP_EXTRACT(tpm.dob_raw, \'(\\\\d{4})$\', 1) AS INT) AS dob_year\n  FROM genealogy.silver_transcript_person_mention tpm\n  WHERE tpm.role_in_record IN (\'Father\',\'Mother\',\'Grandfather\',\'Grandmother\',\'Brother\',\'Sister\',\n        \'Grandson\',\'Granddaughter\',\'Grandchild\',\'Grand Son\',\'Grand Daughter\')\n    AND tpm.override_person_gedcom_id IS NULL\n    AND tpm.file_id IN (SELECT file_id FROM tmp_scope)\n),\n\n-- PARENT emits both parents as separate rows (fixes Cell 5e\'s original\n-- single-parent CASE, which only ever returned one -- see Cell 5f markdown).\n-- GRANDPARENT is one more family_child hop each side; SIBLING is other\n-- children of the primary\'s own parent family; GRANDCHILD is the primary\'s\n-- children\'s own children.\nrelatives AS (\n  SELECT md.file_id, md.year, md.primary_person_id, sf.husband_gedcom_id AS relative_id, \'PARENT\' AS relation\n  FROM matched_docs md\n  JOIN genealogy.silver_family_child fc ON fc.child_gedcom_id = md.primary_person_id\n  JOIN genealogy.silver_family sf ON sf.family_gedcom_id = fc.family_gedcom_id\n  WHERE sf.husband_gedcom_id IS NOT NULL\n\n  UNION ALL\n\n  SELECT md.file_id, md.year, md.primary_person_id, sf.wife_gedcom_id AS relative_id, \'PARENT\' AS relation\n  FROM matched_docs md\n  JOIN genealogy.silver_family_child fc ON fc.child_gedcom_id = md.primary_person_id\n  JOIN genealogy.silver_family sf ON sf.family_gedcom_id = fc.family_gedcom_id\n  WHERE sf.wife_gedcom_id IS NOT NULL\n\n  UNION ALL\n\n  SELECT md.file_id, md.year, md.primary_person_id, sf2.husband_gedcom_id AS relative_id, \'GRANDPARENT\' AS relation\n  FROM matched_docs md\n  JOIN genealogy.silver_family_child fc1 ON fc1.child_gedcom_id = md.primary_person_id\n  JOIN genealogy.silver_family sf1 ON sf1.family_gedcom_id = fc1.family_gedcom_id\n  JOIN genealogy.silver_family_child fc2 ON fc2.child_gedcom_id = sf1.husband_gedcom_id OR fc2.child_gedcom_id = sf1.wife_gedcom_id\n  JOIN genealogy.silver_family sf2 ON sf2.family_gedcom_id = fc2.family_gedcom_id\n  WHERE sf2.husband_gedcom_id IS NOT NULL\n\n  UNION ALL\n\n  SELECT md.file_id, md.year, md.primary_person_id, sf2.wife_gedcom_id AS relative_id, \'GRANDPARENT\' AS relation\n  FROM matched_docs md\n  JOIN genealogy.silver_family_child fc1 ON fc1.child_gedcom_id = md.primary_person_id\n  JOIN genealogy.silver_family sf1 ON sf1.family_gedcom_id = fc1.family_gedcom_id\n  JOIN genealogy.silver_family_child fc2 ON fc2.child_gedcom_id = sf1.husband_gedcom_id OR fc2.child_gedcom_id = sf1.wife_gedcom_id\n  JOIN genealogy.silver_family sf2 ON sf2.family_gedcom_id = fc2.family_gedcom_id\n  WHERE sf2.wife_gedcom_id IS NOT NULL\n\n  UNION ALL\n\n  SELECT md.file_id, md.year, md.primary_person_id, fc_sib.child_gedcom_id AS relative_id, \'SIBLING\' AS relation\n  FROM matched_docs md\n  JOIN genealogy.silver_family_child fc ON fc.child_gedcom_id = md.primary_person_id\n  JOIN genealogy.silver_family_child fc_sib ON fc_sib.family_gedcom_id = fc.family_gedcom_id\n  WHERE fc_sib.child_gedcom_id != md.primary_person_id\n\n  UNION ALL\n\n  SELECT md.file_id, md.year, md.primary_person_id, fc_gc.child_gedcom_id AS relative_id, \'GRANDCHILD\' AS relation\n  FROM matched_docs md\n  JOIN genealogy.silver_family sf_c ON sf_c.husband_gedcom_id = md.primary_person_id OR sf_c.wife_gedcom_id = md.primary_person_id\n  JOIN genealogy.silver_family_child fc_c ON fc_c.family_gedcom_id = sf_c.family_gedcom_id\n  JOIN genealogy.silver_family sf_gc ON sf_gc.husband_gedcom_id = fc_c.child_gedcom_id OR sf_gc.wife_gedcom_id = fc_c.child_gedcom_id\n  JOIN genealogy.silver_family_child fc_gc ON fc_gc.family_gedcom_id = sf_gc.family_gedcom_id\n),\n\nrelatives_named AS (\n  SELECT DISTINCT r.file_id, r.year, r.relation, r.relative_id,\n    COALESCE(pl.given_name, \'\') AS given_name, COALESCE(pl.surname, \'\') AS surname,\n    pl.birth_year, pl.death_year\n  FROM relatives r\n  JOIN genealogy.gold_person_life pl ON pl.person_gedcom_id = r.relative_id\n  WHERE r.relative_id IS NOT NULL AND r.relative_id != r.primary_person_id\n),\n\ncandidate_names AS (\n  SELECT file_id, year, relation, relative_id, birth_year, death_year,\n    COALESCE((SELECT MAX(ab.full_name) FROM genealogy.ref_forename_abbreviation ab WHERE ab.abbr = UPPER(TRIM(REGEXP_EXTRACT(given_name, \'^(\\\\S+)\', 1)))), UPPER(TRIM(REGEXP_EXTRACT(given_name, \'^(\\\\S+)\', 1)))) AS forename_first, UPPER(TRIM(surname)) AS surname\n  FROM relatives_named\n  WHERE surname != \'\'\n\n  UNION ALL\n\n  SELECT rn.file_id, rn.year, rn.relation, rn.relative_id, rn.birth_year, rn.death_year,\n    COALESCE((SELECT MAX(ab.full_name) FROM genealogy.ref_forename_abbreviation ab WHERE ab.abbr = UPPER(TRIM(REGEXP_EXTRACT(a.alias_given_name, \'^(\\\\S+)\', 1)))), UPPER(TRIM(REGEXP_EXTRACT(a.alias_given_name, \'^(\\\\S+)\', 1)))) AS forename_first, UPPER(TRIM(a.alias_surname)) AS surname\n  FROM relatives_named rn\n  JOIN genealogy.silver_person_alias a ON a.person_gedcom_id = rn.relative_id\n  WHERE a.alias_surname IS NOT NULL AND a.alias_surname != \'\'\n),\n\ncandidate_matches AS (\n  SELECT DISTINCT c.file_id, c.relation, c.relative_id, c.birth_year, m.person_index, m.name_raw,\n    CASE\n      WHEN m.age_years IS NOT NULL THEN TRY_CAST(SUBSTR(c.year, 1, 4) AS INT) - m.age_years\n      WHEN m.dob_year IS NOT NULL THEN m.dob_year\n    END AS implied_birth_year\n  FROM candidate_names c\n  JOIN mentions m\n    ON m.file_id = c.file_id AND m.mapped_relation = c.relation\n   AND m.forename_first = c.forename_first AND m.surname_last = c.surname\n  WHERE c.birth_year <= TRY_CAST(SUBSTR(c.year, 1, 4) AS INT)\n    AND (c.death_year IS NULL OR c.death_year >= TRY_CAST(SUBSTR(c.year, 1, 4) AS INT))\n    -- Census age gate, as Cell 5e (single-candidate matches are checked too).\n    AND NOT (m.doc_type = \'Census\' AND m.age_years IS NOT NULL AND c.birth_year IS NOT NULL\n             AND ABS(TRY_CAST(SUBSTR(c.year, 1, 4) AS INT) - m.age_years - c.birth_year) > 5)\n),\n\nmention_candidate_counts AS (\n  SELECT file_id, person_index, COUNT(DISTINCT relative_id) AS n_candidates\n  FROM candidate_matches GROUP BY file_id, person_index\n),\n\nranked AS (\n  SELECT cm.*, mcc.n_candidates,\n    ROW_NUMBER() OVER (\n      PARTITION BY cm.file_id, cm.person_index\n      ORDER BY ABS(COALESCE(cm.implied_birth_year, cm.birth_year) - cm.birth_year) ASC, cm.relative_id ASC\n    ) AS rk\n  FROM candidate_matches cm\n  JOIN mention_candidate_counts mcc ON mcc.file_id = cm.file_id AND mcc.person_index = cm.person_index\n),\n\nfinal AS (\n  SELECT file_id, relative_id, relation, MIN(person_index) AS person_index\n  FROM ranked\n  WHERE n_candidates = 1 OR rk = 1\n  GROUP BY file_id, relative_id, relation\n)\n\nSELECT\n  f.file_id,\n  md.file_name,\n  f.relative_id AS person_gedcom_id,\n  pl.given_name || \' \' || pl.surname AS display_name,\n  \'HOUSEHOLD_INFERENCE_V2\' AS match_method,\n  \'MEDIUM\' AS match_confidence,\n  1 AS candidate_count,\n  CONCAT(\'Household member (\', f.relation, \') matched via silver_transcript_person_mention\') AS notes,\n  CURRENT_TIMESTAMP()\nFROM final f\nJOIN matched_docs md ON md.file_id = f.file_id\nJOIN genealogy.gold_person_life pl ON pl.person_gedcom_id = f.relative_id\nWHERE NOT EXISTS (\n  SELECT 1 FROM genealogy.silver_document_person sdp\n  WHERE sdp.file_id = f.file_id AND sdp.person_gedcom_id = f.relative_id\n)', '5g': '-- Cell 5g — Tier 2 step 1: Witness/Executor/Legatee via the whole family pool\n\n\nWITH\n\n-- Restricted to the TRUE primary match only (Cell 5/5b/5c\'s own methods).\n-- Bug found live this session: without this filter, once Cell 5g/5h/5f have\n-- written their own inferred rows to silver_document_person, a later cell\n-- re-deriving matched_docs from the same table picks those rows up as if\n-- they were additional "primaries" too -- e.g. after Cell 5g matched Clara\n-- as Executor (SPOUSE relation) on Charles Edward Ball\'s 1934 will, Cell 5h\n-- treated CLARA as a second primary and computed her own SIBLING (Samuel\n-- Mattock) as if he were related to Charles Edward Ball directly -- silently\n-- causing Cell 5h to skip its whole-tree fallback for him, thinking Cell 5g\n-- had already covered it. Excluding this session\'s two new match_methods\n-- keeps every cell\'s candidate pool anchored to the one true primary.\nmatched_docs AS (\n  SELECT sdp.file_id, sdp.person_gedcom_id AS primary_person_id, ot.year, ot.file_name\n  FROM genealogy.silver_document_person sdp\n  JOIN genealogy.ocr_transcriptions ot ON ot.file_id = sdp.file_id\n  WHERE sdp.file_id IN (SELECT DISTINCT file_id FROM genealogy.silver_transcript_person_mention)\n    AND sdp.file_id IN (SELECT file_id FROM tmp_scope)\n    AND sdp.match_method NOT IN (\'HOUSEHOLD_INFERENCE_V2\', \'WHOLE_TREE_NAME_MATCH\', \'MENTION_OVERRIDE\')\n  GROUP BY sdp.file_id, sdp.person_gedcom_id, ot.year, ot.file_name\n),\n\n-- Testator deliberately absent: it IS the document\'s own already-matched\n-- primary person (Cell 5/5b/5c) -- see Cell 5f markdown.\nmentions AS (\n  SELECT tpm.file_id, tpm.person_index, tpm.name_raw, tpm.role_in_record, tpm.age_years, tpm.dob_raw,\n    (SELECT MAX(o.doc_type_detected) FROM genealogy.ocr_transcriptions o WHERE o.file_id = tpm.file_id) AS doc_type,\n    COALESCE((SELECT MAX(ab.full_name) FROM genealogy.ref_forename_abbreviation ab WHERE ab.abbr = UPPER(TRIM(REGEXP_EXTRACT(tpm.name_raw, \'^(\\\\S+)\', 1)))), UPPER(TRIM(REGEXP_EXTRACT(tpm.name_raw, \'^(\\\\S+)\', 1)))) AS forename_first,\n    UPPER(TRIM(REGEXP_EXTRACT(tpm.name_raw, \'(\\\\S+)$\', 1))) AS surname_last,\n    TRY_CAST(REGEXP_EXTRACT(tpm.dob_raw, \'(\\\\d{4})$\', 1) AS INT) AS dob_year\n  FROM genealogy.silver_transcript_person_mention tpm\n  WHERE tpm.role_in_record IN (\'Witness\',\'Executor\',\'Legatee\',\'Resident\')\n    AND tpm.override_person_gedcom_id IS NULL\n    AND tpm.file_id IN (SELECT file_id FROM tmp_scope)\n),\n\n-- Full family relation pool -- unlike Tier 1 mentions (which must land on a\n-- specific relation type), a Witness/Executor/Legatee could turn out to be\n-- ANY relation to the primary person (e.g. Clara Ball as Executor on her own\n-- husband\'s will is his SPOUSE) -- see Cell 5f markdown.\nrelatives AS (\n  SELECT md.file_id, md.year, md.primary_person_id,\n    CASE WHEN sf.husband_gedcom_id = md.primary_person_id THEN sf.wife_gedcom_id ELSE sf.husband_gedcom_id END AS relative_id,\n    \'SPOUSE\' AS relation\n  FROM matched_docs md\n  JOIN genealogy.silver_family sf ON sf.husband_gedcom_id = md.primary_person_id OR sf.wife_gedcom_id = md.primary_person_id\n  WHERE sf.relationship_type IS NULL\n\n  UNION ALL\n\n  SELECT md.file_id, md.year, md.primary_person_id, fc.child_gedcom_id, \'CHILD\'\n  FROM matched_docs md\n  JOIN genealogy.silver_family sf ON sf.husband_gedcom_id = md.primary_person_id OR sf.wife_gedcom_id = md.primary_person_id\n  JOIN genealogy.silver_family_child fc ON fc.family_gedcom_id = sf.family_gedcom_id\n\n  UNION ALL\n\n  SELECT md.file_id, md.year, md.primary_person_id, sf.husband_gedcom_id, \'PARENT\'\n  FROM matched_docs md\n  JOIN genealogy.silver_family_child fc ON fc.child_gedcom_id = md.primary_person_id\n  JOIN genealogy.silver_family sf ON sf.family_gedcom_id = fc.family_gedcom_id\n  WHERE sf.husband_gedcom_id IS NOT NULL\n\n  UNION ALL\n\n  SELECT md.file_id, md.year, md.primary_person_id, sf.wife_gedcom_id, \'PARENT\'\n  FROM matched_docs md\n  JOIN genealogy.silver_family_child fc ON fc.child_gedcom_id = md.primary_person_id\n  JOIN genealogy.silver_family sf ON sf.family_gedcom_id = fc.family_gedcom_id\n  WHERE sf.wife_gedcom_id IS NOT NULL\n\n  UNION ALL\n\n  SELECT md.file_id, md.year, md.primary_person_id, sf2.husband_gedcom_id, \'GRANDPARENT\'\n  FROM matched_docs md\n  JOIN genealogy.silver_family_child fc1 ON fc1.child_gedcom_id = md.primary_person_id\n  JOIN genealogy.silver_family sf1 ON sf1.family_gedcom_id = fc1.family_gedcom_id\n  JOIN genealogy.silver_family_child fc2 ON fc2.child_gedcom_id = sf1.husband_gedcom_id OR fc2.child_gedcom_id = sf1.wife_gedcom_id\n  JOIN genealogy.silver_family sf2 ON sf2.family_gedcom_id = fc2.family_gedcom_id\n  WHERE sf2.husband_gedcom_id IS NOT NULL\n\n  UNION ALL\n\n  SELECT md.file_id, md.year, md.primary_person_id, sf2.wife_gedcom_id, \'GRANDPARENT\'\n  FROM matched_docs md\n  JOIN genealogy.silver_family_child fc1 ON fc1.child_gedcom_id = md.primary_person_id\n  JOIN genealogy.silver_family sf1 ON sf1.family_gedcom_id = fc1.family_gedcom_id\n  JOIN genealogy.silver_family_child fc2 ON fc2.child_gedcom_id = sf1.husband_gedcom_id OR fc2.child_gedcom_id = sf1.wife_gedcom_id\n  JOIN genealogy.silver_family sf2 ON sf2.family_gedcom_id = fc2.family_gedcom_id\n  WHERE sf2.wife_gedcom_id IS NOT NULL\n\n  UNION ALL\n\n  SELECT md.file_id, md.year, md.primary_person_id, fc_sib.child_gedcom_id, \'SIBLING\'\n  FROM matched_docs md\n  JOIN genealogy.silver_family_child fc ON fc.child_gedcom_id = md.primary_person_id\n  JOIN genealogy.silver_family_child fc_sib ON fc_sib.family_gedcom_id = fc.family_gedcom_id\n  WHERE fc_sib.child_gedcom_id != md.primary_person_id\n\n  UNION ALL\n\n  SELECT md.file_id, md.year, md.primary_person_id, fc_gc.child_gedcom_id, \'GRANDCHILD\'\n  FROM matched_docs md\n  JOIN genealogy.silver_family sf_c ON sf_c.husband_gedcom_id = md.primary_person_id OR sf_c.wife_gedcom_id = md.primary_person_id\n  JOIN genealogy.silver_family_child fc_c ON fc_c.family_gedcom_id = sf_c.family_gedcom_id\n  JOIN genealogy.silver_family sf_gc ON sf_gc.husband_gedcom_id = fc_c.child_gedcom_id OR sf_gc.wife_gedcom_id = fc_c.child_gedcom_id\n  JOIN genealogy.silver_family_child fc_gc ON fc_gc.family_gedcom_id = sf_gc.family_gedcom_id\n),\n\nrelatives_named AS (\n  SELECT DISTINCT r.file_id, r.year, r.relation, r.relative_id,\n    COALESCE(pl.given_name, \'\') AS given_name, COALESCE(pl.surname, \'\') AS surname,\n    pl.birth_year, pl.death_year\n  FROM relatives r\n  JOIN genealogy.gold_person_life pl ON pl.person_gedcom_id = r.relative_id\n  WHERE r.relative_id IS NOT NULL AND r.relative_id != r.primary_person_id\n),\n\ncandidate_names AS (\n  SELECT file_id, year, relation, relative_id, birth_year, death_year,\n    COALESCE((SELECT MAX(ab.full_name) FROM genealogy.ref_forename_abbreviation ab WHERE ab.abbr = UPPER(TRIM(REGEXP_EXTRACT(given_name, \'^(\\\\S+)\', 1)))), UPPER(TRIM(REGEXP_EXTRACT(given_name, \'^(\\\\S+)\', 1)))) AS forename_first, UPPER(TRIM(surname)) AS surname\n  FROM relatives_named\n  WHERE surname != \'\'\n\n  UNION ALL\n\n  SELECT rn.file_id, rn.year, rn.relation, rn.relative_id, rn.birth_year, rn.death_year,\n    COALESCE((SELECT MAX(ab.full_name) FROM genealogy.ref_forename_abbreviation ab WHERE ab.abbr = UPPER(TRIM(REGEXP_EXTRACT(a.alias_given_name, \'^(\\\\S+)\', 1)))), UPPER(TRIM(REGEXP_EXTRACT(a.alias_given_name, \'^(\\\\S+)\', 1)))) AS forename_first, UPPER(TRIM(a.alias_surname)) AS surname\n  FROM relatives_named rn\n  JOIN genealogy.silver_person_alias a ON a.person_gedcom_id = rn.relative_id\n  WHERE a.alias_surname IS NOT NULL AND a.alias_surname != \'\'\n),\n\n-- A Resident whose name is the primary\'s own (a page about Alfred Pearson listing "Alfred Pearson")\n-- is the primary, not a same-named child, so it is never offered to the family pool.\nprimary_names AS (\n  SELECT DISTINCT md.file_id, COALESCE((SELECT MAX(ab.full_name) FROM genealogy.ref_forename_abbreviation ab WHERE ab.abbr = UPPER(TRIM(REGEXP_EXTRACT(pl.given_name, \'^(\\\\S+)\', 1)))), UPPER(TRIM(REGEXP_EXTRACT(pl.given_name, \'^(\\\\S+)\', 1)))) AS forename_first, UPPER(TRIM(pl.surname)) AS surname\n  FROM matched_docs md\n  JOIN genealogy.gold_person_life pl ON pl.person_gedcom_id = md.primary_person_id\n  WHERE pl.surname IS NOT NULL AND pl.surname != \'\'\n\n  UNION\n\n  SELECT DISTINCT md.file_id, COALESCE((SELECT MAX(ab.full_name) FROM genealogy.ref_forename_abbreviation ab WHERE ab.abbr = UPPER(TRIM(REGEXP_EXTRACT(a.alias_given_name, \'^(\\\\S+)\', 1)))), UPPER(TRIM(REGEXP_EXTRACT(a.alias_given_name, \'^(\\\\S+)\', 1)))) AS forename_first, UPPER(TRIM(a.alias_surname)) AS surname\n  FROM matched_docs md\n  JOIN genealogy.silver_person_alias a ON a.person_gedcom_id = md.primary_person_id\n  WHERE a.alias_surname IS NOT NULL AND a.alias_surname != \'\'\n),\n\ncandidate_matches AS (\n  SELECT DISTINCT c.file_id, c.relation, c.relative_id, c.birth_year, m.person_index, m.name_raw, m.role_in_record,\n    CASE\n      WHEN m.age_years IS NOT NULL THEN TRY_CAST(SUBSTR(c.year, 1, 4) AS INT) - m.age_years\n      WHEN m.dob_year IS NOT NULL THEN m.dob_year\n    END AS implied_birth_year\n  FROM candidate_names c\n  JOIN mentions m\n    ON m.file_id = c.file_id AND m.forename_first = c.forename_first AND m.surname_last = c.surname\n  LEFT JOIN primary_names pn\n    ON pn.file_id = m.file_id AND pn.forename_first = m.forename_first AND pn.surname = m.surname_last\n   AND m.role_in_record = \'Resident\'\n  WHERE pn.file_id IS NULL\n    AND c.birth_year <= TRY_CAST(SUBSTR(c.year, 1, 4) AS INT)\n    AND (c.death_year IS NULL OR c.death_year >= TRY_CAST(SUBSTR(c.year, 1, 4) AS INT))\n    -- Resident carries no relation, so a stated date of birth (1939 Register) must agree with the tree.\n    AND NOT (m.role_in_record = \'Resident\' AND m.dob_year IS NOT NULL AND c.birth_year IS NOT NULL\n             AND ABS(m.dob_year - c.birth_year) > 5)\n    -- A Resident with neither age nor date of birth cannot be told from a same-named relative, and the pool\n    -- has no children\'s spouses (found live: sons-in-law John Pearson and Samuel Palmer were matched as\n    -- grandchildren), so such a mention does not link through GRANDPARENT or GRANDCHILD.\n    AND NOT (m.role_in_record = \'Resident\' AND m.age_years IS NULL AND m.dob_year IS NULL\n             AND c.relation IN (\'GRANDPARENT\', \'GRANDCHILD\'))\n    -- Census age gate, as Cell 5e (single-candidate matches are checked too).\n    AND NOT (m.doc_type = \'Census\' AND m.age_years IS NOT NULL AND c.birth_year IS NOT NULL\n             AND ABS(TRY_CAST(SUBSTR(c.year, 1, 4) AS INT) - m.age_years - c.birth_year) > 5)\n),\n\nmention_candidate_counts AS (\n  SELECT file_id, person_index, COUNT(DISTINCT relative_id) AS n_candidates\n  FROM candidate_matches GROUP BY file_id, person_index\n),\n\nranked AS (\n  SELECT cm.*, mcc.n_candidates,\n    ROW_NUMBER() OVER (\n      PARTITION BY cm.file_id, cm.person_index\n      ORDER BY ABS(COALESCE(cm.implied_birth_year, cm.birth_year) - cm.birth_year) ASC, cm.relative_id ASC\n    ) AS rk\n  FROM candidate_matches cm\n  JOIN mention_candidate_counts mcc ON mcc.file_id = cm.file_id AND mcc.person_index = cm.person_index\n),\n\nfinal AS (\n  SELECT file_id, relative_id, relation, role_in_record, MIN(person_index) AS person_index\n  FROM ranked\n  WHERE n_candidates = 1 OR rk = 1\n  GROUP BY file_id, relative_id, relation, role_in_record\n)\n\nSELECT\n  f.file_id,\n  md.file_name,\n  f.relative_id AS person_gedcom_id,\n  pl.given_name || \' \' || pl.surname AS display_name,\n  \'HOUSEHOLD_INFERENCE_V2\' AS match_method,\n  \'MEDIUM\' AS match_confidence,\n  1 AS candidate_count,\n  CONCAT(f.role_in_record, \' matched via \', f.relation, \' relation\') AS notes,\n  CURRENT_TIMESTAMP()\nFROM final f\nJOIN matched_docs md ON md.file_id = f.file_id\nJOIN genealogy.gold_person_life pl ON pl.person_gedcom_id = f.relative_id\nWHERE NOT EXISTS (\n  SELECT 1 FROM genealogy.silver_document_person sdp\n  WHERE sdp.file_id = f.file_id AND sdp.person_gedcom_id = f.relative_id\n)', '5h': '-- Cell 5h — Tier 2 step 2: whole-tree name + year-plausibility fallback\n\n\nWITH\n\n-- Restricted to the TRUE primary match only (Cell 5/5b/5c\'s own methods) --\n-- see the note on Cell 5f\'s matched_docs for why.\nmatched_docs AS (\n  SELECT sdp.file_id, sdp.person_gedcom_id AS primary_person_id, ot.year, ot.file_name\n  FROM genealogy.silver_document_person sdp\n  JOIN genealogy.ocr_transcriptions ot ON ot.file_id = sdp.file_id\n  WHERE sdp.file_id IN (SELECT DISTINCT file_id FROM genealogy.silver_transcript_person_mention)\n    AND sdp.file_id IN (SELECT file_id FROM tmp_scope)\n    AND sdp.match_method NOT IN (\'HOUSEHOLD_INFERENCE_V2\', \'WHOLE_TREE_NAME_MATCH\', \'MENTION_OVERRIDE\')\n  GROUP BY sdp.file_id, sdp.person_gedcom_id, ot.year, ot.file_name\n),\n\nmentions AS (\n  SELECT tpm.file_id, tpm.person_index, tpm.name_raw, tpm.role_in_record, tpm.age_years, tpm.dob_raw,\n    COALESCE((SELECT MAX(ab.full_name) FROM genealogy.ref_forename_abbreviation ab WHERE ab.abbr = UPPER(TRIM(REGEXP_EXTRACT(tpm.name_raw, \'^(\\\\S+)\', 1)))), UPPER(TRIM(REGEXP_EXTRACT(tpm.name_raw, \'^(\\\\S+)\', 1)))) AS forename_first,\n    UPPER(TRIM(REGEXP_EXTRACT(tpm.name_raw, \'(\\\\S+)$\', 1))) AS surname_last,\n    -- Everything before the surname (e.g. "Joan Margaret" from "Joan Margaret\n    -- Ball") -- used below to prefer a candidate whose full given name\n    -- matches, not just the first token. Found live: without this, "Joan\n    -- Margaret Ball" (forename_first=JOAN) spuriously tied against an\n    -- unrelated "Joan Hobson" whose married-name alias was just "Joan Ball"\n    -- (no Margaret at all) -- both satisfied the old forename_first+surname\n    -- check equally, producing a false LOW-confidence tie between one real\n    -- match and one same-first-name-only person.\n    UPPER(TRIM(REGEXP_REPLACE(tpm.name_raw, \'\\\\s+\\\\S+$\', \'\'))) AS full_forename,\n    TRY_CAST(REGEXP_EXTRACT(tpm.dob_raw, \'(\\\\d{4})$\', 1) AS INT) AS dob_year\n  FROM genealogy.silver_transcript_person_mention tpm\n  WHERE tpm.role_in_record IN (\'Witness\',\'Executor\',\'Legatee\')\n    AND tpm.override_person_gedcom_id IS NULL\n    AND tpm.file_id IN (SELECT file_id FROM tmp_scope)\n),\n\n-- Same family relation pool as Cell 5g, collapsed to just names, used here\n-- only to test "did Cell 5g\'s step 1 have ANY family candidate for this\n-- mention" -- independent of whether Cell 5g has actually run yet, so this\n-- cell is correct standalone as well as run after 5g.\nrelatives AS (\n  SELECT md.file_id,\n    CASE WHEN sf.husband_gedcom_id = md.primary_person_id THEN sf.wife_gedcom_id ELSE sf.husband_gedcom_id END AS relative_id\n  FROM matched_docs md\n  JOIN genealogy.silver_family sf ON sf.husband_gedcom_id = md.primary_person_id OR sf.wife_gedcom_id = md.primary_person_id\n  WHERE sf.relationship_type IS NULL\n\n  UNION ALL\n\n  SELECT md.file_id, fc.child_gedcom_id\n  FROM matched_docs md\n  JOIN genealogy.silver_family sf ON sf.husband_gedcom_id = md.primary_person_id OR sf.wife_gedcom_id = md.primary_person_id\n  JOIN genealogy.silver_family_child fc ON fc.family_gedcom_id = sf.family_gedcom_id\n\n  UNION ALL\n\n  SELECT md.file_id, sf.husband_gedcom_id\n  FROM matched_docs md\n  JOIN genealogy.silver_family_child fc ON fc.child_gedcom_id = md.primary_person_id\n  JOIN genealogy.silver_family sf ON sf.family_gedcom_id = fc.family_gedcom_id\n  WHERE sf.husband_gedcom_id IS NOT NULL\n\n  UNION ALL\n\n  SELECT md.file_id, sf.wife_gedcom_id\n  FROM matched_docs md\n  JOIN genealogy.silver_family_child fc ON fc.child_gedcom_id = md.primary_person_id\n  JOIN genealogy.silver_family sf ON sf.family_gedcom_id = fc.family_gedcom_id\n  WHERE sf.wife_gedcom_id IS NOT NULL\n\n  UNION ALL\n\n  SELECT md.file_id, sf2.husband_gedcom_id\n  FROM matched_docs md\n  JOIN genealogy.silver_family_child fc1 ON fc1.child_gedcom_id = md.primary_person_id\n  JOIN genealogy.silver_family sf1 ON sf1.family_gedcom_id = fc1.family_gedcom_id\n  JOIN genealogy.silver_family_child fc2 ON fc2.child_gedcom_id = sf1.husband_gedcom_id OR fc2.child_gedcom_id = sf1.wife_gedcom_id\n  JOIN genealogy.silver_family sf2 ON sf2.family_gedcom_id = fc2.family_gedcom_id\n  WHERE sf2.husband_gedcom_id IS NOT NULL\n\n  UNION ALL\n\n  SELECT md.file_id, sf2.wife_gedcom_id\n  FROM matched_docs md\n  JOIN genealogy.silver_family_child fc1 ON fc1.child_gedcom_id = md.primary_person_id\n  JOIN genealogy.silver_family sf1 ON sf1.family_gedcom_id = fc1.family_gedcom_id\n  JOIN genealogy.silver_family_child fc2 ON fc2.child_gedcom_id = sf1.husband_gedcom_id OR fc2.child_gedcom_id = sf1.wife_gedcom_id\n  JOIN genealogy.silver_family sf2 ON sf2.family_gedcom_id = fc2.family_gedcom_id\n  WHERE sf2.wife_gedcom_id IS NOT NULL\n\n  UNION ALL\n\n  SELECT md.file_id, fc_sib.child_gedcom_id\n  FROM matched_docs md\n  JOIN genealogy.silver_family_child fc ON fc.child_gedcom_id = md.primary_person_id\n  JOIN genealogy.silver_family_child fc_sib ON fc_sib.family_gedcom_id = fc.family_gedcom_id\n  WHERE fc_sib.child_gedcom_id != md.primary_person_id\n\n  UNION ALL\n\n  SELECT md.file_id, fc_gc.child_gedcom_id\n  FROM matched_docs md\n  JOIN genealogy.silver_family sf_c ON sf_c.husband_gedcom_id = md.primary_person_id OR sf_c.wife_gedcom_id = md.primary_person_id\n  JOIN genealogy.silver_family_child fc_c ON fc_c.family_gedcom_id = sf_c.family_gedcom_id\n  JOIN genealogy.silver_family sf_gc ON sf_gc.husband_gedcom_id = fc_c.child_gedcom_id OR sf_gc.wife_gedcom_id = fc_c.child_gedcom_id\n  JOIN genealogy.silver_family_child fc_gc ON fc_gc.family_gedcom_id = sf_gc.family_gedcom_id\n),\n\ncandidate_names AS (\n  SELECT DISTINCT r.file_id,\n    COALESCE((SELECT MAX(ab.full_name) FROM genealogy.ref_forename_abbreviation ab WHERE ab.abbr = UPPER(TRIM(REGEXP_EXTRACT(pl.given_name, \'^(\\\\S+)\', 1)))), UPPER(TRIM(REGEXP_EXTRACT(pl.given_name, \'^(\\\\S+)\', 1)))) AS forename_first, UPPER(TRIM(pl.surname)) AS surname\n  FROM relatives r\n  JOIN genealogy.gold_person_life pl ON pl.person_gedcom_id = r.relative_id\n  WHERE r.relative_id IS NOT NULL AND pl.surname IS NOT NULL AND pl.surname != \'\'\n\n  UNION\n\n  SELECT DISTINCT r.file_id,\n    COALESCE((SELECT MAX(ab.full_name) FROM genealogy.ref_forename_abbreviation ab WHERE ab.abbr = UPPER(TRIM(REGEXP_EXTRACT(a.alias_given_name, \'^(\\\\S+)\', 1)))), UPPER(TRIM(REGEXP_EXTRACT(a.alias_given_name, \'^(\\\\S+)\', 1)))) AS forename_first, UPPER(TRIM(a.alias_surname)) AS surname\n  FROM relatives r\n  JOIN genealogy.silver_person_alias a ON a.person_gedcom_id = r.relative_id\n  WHERE r.relative_id IS NOT NULL AND a.alias_surname IS NOT NULL AND a.alias_surname != \'\'\n),\n\n-- Tree and alias given names with the same abbreviation lookup the mentions use\n-- (ref_forename_abbreviation, Cell 4d), so Geo matches George here too.\nperson_canon AS (\n  SELECT p.*, COALESCE((SELECT MAX(ab.full_name) FROM genealogy.ref_forename_abbreviation ab WHERE ab.abbr = UPPER(TRIM(REGEXP_EXTRACT(p.given_name, \'^(\\\\S+)\', 1)))), UPPER(TRIM(REGEXP_EXTRACT(p.given_name, \'^(\\\\S+)\', 1)))) AS forename_canon\n  FROM genealogy.gold_person_life p\n  -- Only surnames that a mention in scope can join on below (whole_tree_candidates requires\n  -- UPPER(TRIM(surname)) = the mention\'s surname_last): same result, without the per-row\n  -- abbreviation lookup over the whole tree.\n  WHERE UPPER(TRIM(p.surname)) IN (SELECT surname_last FROM mentions)\n),\n\nalias_canon AS (\n  SELECT a.*, COALESCE((SELECT MAX(ab.full_name) FROM genealogy.ref_forename_abbreviation ab WHERE ab.abbr = UPPER(TRIM(REGEXP_EXTRACT(a.alias_given_name, \'^(\\\\S+)\', 1)))), UPPER(TRIM(REGEXP_EXTRACT(a.alias_given_name, \'^(\\\\S+)\', 1)))) AS forename_canon\n  FROM genealogy.silver_person_alias a\n  WHERE UPPER(TRIM(a.alias_surname)) IN (SELECT surname_last FROM mentions)\n),\n\n-- Mentions the family pool has zero candidates for -- these are the ones\n-- Cell 5g\'s step 1 could never have matched, so they fall to the whole-tree\n-- search below.\ntier2_unresolved AS (\n  SELECT m.file_id, m.person_index, m.name_raw, m.role_in_record, m.forename_first, m.surname_last,\n    m.full_forename, m.age_years, m.dob_year\n  FROM mentions m\n  WHERE NOT EXISTS (\n    SELECT 1 FROM candidate_names c\n    WHERE c.file_id = m.file_id AND c.forename_first = m.forename_first AND c.surname = m.surname_last\n  )\n),\n\n-- Same mechanism Cell 5\'s own primary matcher uses (name match + alive-at-\n-- document-year plausibility), applied to a secondary name instead of the\n-- document\'s main subject.\nwhole_tree_candidates AS (\n  SELECT tu.file_id, tu.person_index, tu.name_raw, tu.role_in_record,\n    p.person_gedcom_id, p.given_name, p.surname, p.birth_year, p.death_year,\n    CASE WHEN UPPER(TRIM(p.given_name)) = tu.full_forename THEN 1 ELSE 0 END AS full_name_match,\n    CASE\n      WHEN tu.age_years IS NOT NULL THEN TRY_CAST(SUBSTR(md.year, 1, 4) AS INT) - tu.age_years\n      WHEN tu.dob_year IS NOT NULL THEN tu.dob_year\n    END AS implied_birth_year\n  FROM tier2_unresolved tu\n  JOIN matched_docs md ON md.file_id = tu.file_id\n  JOIN person_canon p\n    ON p.forename_canon = tu.forename_first\n   AND UPPER(TRIM(p.surname)) = tu.surname_last\n  WHERE p.person_gedcom_id != md.primary_person_id\n    AND p.birth_year <= TRY_CAST(SUBSTR(md.year, 1, 4) AS INT)\n    AND (p.death_year IS NULL OR p.death_year >= TRY_CAST(SUBSTR(md.year, 1, 4) AS INT))\n\n  UNION ALL\n\n  SELECT tu.file_id, tu.person_index, tu.name_raw, tu.role_in_record,\n    a.person_gedcom_id, pl.given_name, pl.surname, pl.birth_year, pl.death_year,\n    CASE WHEN UPPER(TRIM(a.alias_given_name)) = tu.full_forename THEN 1 ELSE 0 END AS full_name_match,\n    CASE\n      WHEN tu.age_years IS NOT NULL THEN TRY_CAST(SUBSTR(md.year, 1, 4) AS INT) - tu.age_years\n      WHEN tu.dob_year IS NOT NULL THEN tu.dob_year\n    END AS implied_birth_year\n  FROM tier2_unresolved tu\n  JOIN matched_docs md ON md.file_id = tu.file_id\n  JOIN alias_canon a\n    ON a.forename_canon = tu.forename_first\n   AND UPPER(TRIM(a.alias_surname)) = tu.surname_last\n  JOIN genealogy.gold_person_life pl ON pl.person_gedcom_id = a.person_gedcom_id\n  WHERE a.person_gedcom_id != md.primary_person_id\n    AND pl.birth_year <= TRY_CAST(SUBSTR(md.year, 1, 4) AS INT)\n    AND (pl.death_year IS NULL OR pl.death_year >= TRY_CAST(SUBSTR(md.year, 1, 4) AS INT))\n),\n\n-- Prefer full-given-name matches over first-token-only matches: if any\n-- candidate for a mention matches the full forename, first-token-only\n-- candidates are dropped entirely rather than counted as competing ties.\nbest_tier AS (\n  SELECT file_id, person_index, MAX(full_name_match) AS best_full_match\n  FROM whole_tree_candidates\n  GROUP BY file_id, person_index\n),\n\nwhole_tree_filtered AS (\n  SELECT wtc.*\n  FROM whole_tree_candidates wtc\n  JOIN best_tier bt ON bt.file_id = wtc.file_id AND bt.person_index = wtc.person_index\n  WHERE wtc.full_name_match = bt.best_full_match\n),\n\nwhole_tree_counts AS (\n  SELECT file_id, person_index, COUNT(DISTINCT person_gedcom_id) AS n_candidates\n  FROM whole_tree_filtered GROUP BY file_id, person_index\n),\n\n-- Distance from implied_birth_year (age/DOB on the mention, if any) breaks a\n-- genuine tie when possible; person_gedcom_id ASC is the last-resort,\n-- arbitrary tie-break otherwise -- flagged LOW confidence below, same\n-- convention as Cell 5\'s own TIE handling, not asserted as a real match.\nwhole_tree_ranked AS (\n  SELECT wtc.*, cnt.n_candidates,\n    ROW_NUMBER() OVER (\n      PARTITION BY wtc.file_id, wtc.person_index\n      ORDER BY ABS(COALESCE(wtc.implied_birth_year, wtc.birth_year) - wtc.birth_year) ASC, wtc.person_gedcom_id ASC\n    ) AS rk\n  FROM whole_tree_filtered wtc\n  JOIN whole_tree_counts cnt ON cnt.file_id = wtc.file_id AND cnt.person_index = wtc.person_index\n)\n\nSELECT\n  f.file_id,\n  md.file_name,\n  f.person_gedcom_id,\n  f.given_name || \' \' || f.surname AS display_name,\n  \'WHOLE_TREE_NAME_MATCH\' AS match_method,\n  CASE WHEN f.n_candidates = 1 THEN \'MEDIUM\' ELSE \'LOW\' END AS match_confidence,\n  f.n_candidates AS candidate_count,\n  CONCAT(f.role_in_record, \' matched via whole-tree name search\',\n    CASE WHEN f.n_candidates > 1\n      THEN CONCAT(\' | TIE: \', f.n_candidates, \' candidates equally plausible, needs manual review\')\n      ELSE \'\' END\n  ) AS notes,\n  CURRENT_TIMESTAMP()\nFROM whole_tree_ranked f\nJOIN matched_docs md ON md.file_id = f.file_id\nWHERE f.rk = 1\n  AND NOT EXISTS (\n    SELECT 1 FROM genealogy.silver_document_person sdp\n    WHERE sdp.file_id = f.file_id AND sdp.person_gedcom_id = f.person_gedcom_id\n  )', '5h3': "-- Cell 5h3 — Household heads: a second household on the page headed by a known relative\n\n\nWITH\n\n-- Same primary-only anchor as Cells 5e-5h.\nmatched_docs AS (\n  SELECT sdp.file_id, sdp.person_gedcom_id AS primary_person_id, ot.year, ot.file_name\n  FROM genealogy.silver_document_person sdp\n  JOIN genealogy.ocr_transcriptions ot ON ot.file_id = sdp.file_id\n  WHERE sdp.file_id IN (SELECT DISTINCT file_id FROM genealogy.silver_transcript_person_mention)\n    AND sdp.file_id IN (SELECT file_id FROM tmp_scope)\n    AND sdp.match_method NOT IN ('HOUSEHOLD_INFERENCE_V2', 'WHOLE_TREE_NAME_MATCH', 'MENTION_OVERRIDE')\n  GROUP BY sdp.file_id, sdp.person_gedcom_id, ot.year, ot.file_name\n),\n\n-- Head mentions that no one has claimed yet. Cell 5h2 has already linked the primary's own\n-- mention, so what is left is a head of another household on the same page.\nmentions AS (\n  SELECT tpm.file_id, tpm.page_index, tpm.person_index, tpm.name_raw, tpm.age_years,\n    ot2.doc_type_detected AS doc_type,\n    COALESCE((SELECT MAX(ab.full_name) FROM genealogy.ref_forename_abbreviation ab WHERE ab.abbr = UPPER(TRIM(REGEXP_EXTRACT(tpm.name_raw, '^(\\\\S+)', 1)))), UPPER(TRIM(REGEXP_EXTRACT(tpm.name_raw, '^(\\\\S+)', 1)))) AS forename_first,\n    UPPER(TRIM(REGEXP_EXTRACT(tpm.name_raw, '(\\\\S+)$', 1))) AS surname_last\n  FROM genealogy.silver_transcript_person_mention tpm\n  JOIN (SELECT DISTINCT file_id, doc_type_detected FROM genealogy.ocr_transcriptions) ot2\n    ON ot2.file_id = tpm.file_id\n  WHERE tpm.role_in_record = 'Head'\n    AND tpm.override_person_gedcom_id IS NULL\n    AND tpm.file_id IN (SELECT file_id FROM tmp_scope)\n    AND tpm.age_years IS NOT NULL\n    AND ot2.doc_type_detected = 'Census'\n    AND NOT EXISTS (\n      SELECT 1 FROM genealogy.silver_document_person o\n      WHERE o.file_id = tpm.file_id AND o.page_index <=> tpm.page_index AND o.person_index = tpm.person_index\n    )\n),\n\n-- The primary's extended family: spouse and children (as Cell 5e) plus parents, grandparents,\n-- siblings and grandchildren (as Cell 5f).\nrelatives AS (\n  SELECT md.file_id, md.year, md.primary_person_id,\n    CASE WHEN sf.husband_gedcom_id = md.primary_person_id THEN sf.wife_gedcom_id ELSE sf.husband_gedcom_id END AS relative_id,\n    'SPOUSE' AS relation\n  FROM matched_docs md\n  JOIN genealogy.silver_family sf\n    ON sf.husband_gedcom_id = md.primary_person_id OR sf.wife_gedcom_id = md.primary_person_id\n  WHERE sf.relationship_type IS NULL\n\n  UNION ALL\n\n  SELECT md.file_id, md.year, md.primary_person_id, fc.child_gedcom_id AS relative_id, 'CHILD' AS relation\n  FROM matched_docs md\n  JOIN genealogy.silver_family sf\n    ON sf.husband_gedcom_id = md.primary_person_id OR sf.wife_gedcom_id = md.primary_person_id\n  JOIN genealogy.silver_family_child fc ON fc.family_gedcom_id = sf.family_gedcom_id\n\n  UNION ALL\n\n  SELECT md.file_id, md.year, md.primary_person_id, sf.husband_gedcom_id AS relative_id, 'PARENT' AS relation\n  FROM matched_docs md\n  JOIN genealogy.silver_family_child fc ON fc.child_gedcom_id = md.primary_person_id\n  JOIN genealogy.silver_family sf ON sf.family_gedcom_id = fc.family_gedcom_id\n  WHERE sf.husband_gedcom_id IS NOT NULL\n\n  UNION ALL\n\n  SELECT md.file_id, md.year, md.primary_person_id, sf.wife_gedcom_id AS relative_id, 'PARENT' AS relation\n  FROM matched_docs md\n  JOIN genealogy.silver_family_child fc ON fc.child_gedcom_id = md.primary_person_id\n  JOIN genealogy.silver_family sf ON sf.family_gedcom_id = fc.family_gedcom_id\n  WHERE sf.wife_gedcom_id IS NOT NULL\n\n  UNION ALL\n\n  SELECT md.file_id, md.year, md.primary_person_id, sf2.husband_gedcom_id AS relative_id, 'GRANDPARENT' AS relation\n  FROM matched_docs md\n  JOIN genealogy.silver_family_child fc1 ON fc1.child_gedcom_id = md.primary_person_id\n  JOIN genealogy.silver_family sf1 ON sf1.family_gedcom_id = fc1.family_gedcom_id\n  JOIN genealogy.silver_family_child fc2 ON fc2.child_gedcom_id = sf1.husband_gedcom_id OR fc2.child_gedcom_id = sf1.wife_gedcom_id\n  JOIN genealogy.silver_family sf2 ON sf2.family_gedcom_id = fc2.family_gedcom_id\n  WHERE sf2.husband_gedcom_id IS NOT NULL\n\n  UNION ALL\n\n  SELECT md.file_id, md.year, md.primary_person_id, sf2.wife_gedcom_id AS relative_id, 'GRANDPARENT' AS relation\n  FROM matched_docs md\n  JOIN genealogy.silver_family_child fc1 ON fc1.child_gedcom_id = md.primary_person_id\n  JOIN genealogy.silver_family sf1 ON sf1.family_gedcom_id = fc1.family_gedcom_id\n  JOIN genealogy.silver_family_child fc2 ON fc2.child_gedcom_id = sf1.husband_gedcom_id OR fc2.child_gedcom_id = sf1.wife_gedcom_id\n  JOIN genealogy.silver_family sf2 ON sf2.family_gedcom_id = fc2.family_gedcom_id\n  WHERE sf2.wife_gedcom_id IS NOT NULL\n\n  UNION ALL\n\n  SELECT md.file_id, md.year, md.primary_person_id, fc_sib.child_gedcom_id AS relative_id, 'SIBLING' AS relation\n  FROM matched_docs md\n  JOIN genealogy.silver_family_child fc ON fc.child_gedcom_id = md.primary_person_id\n  JOIN genealogy.silver_family_child fc_sib ON fc_sib.family_gedcom_id = fc.family_gedcom_id\n  WHERE fc_sib.child_gedcom_id != md.primary_person_id\n\n  UNION ALL\n\n  SELECT md.file_id, md.year, md.primary_person_id, fc_gc.child_gedcom_id AS relative_id, 'GRANDCHILD' AS relation\n  FROM matched_docs md\n  JOIN genealogy.silver_family sf_c ON sf_c.husband_gedcom_id = md.primary_person_id OR sf_c.wife_gedcom_id = md.primary_person_id\n  JOIN genealogy.silver_family_child fc_c ON fc_c.family_gedcom_id = sf_c.family_gedcom_id\n  JOIN genealogy.silver_family sf_gc ON sf_gc.husband_gedcom_id = fc_c.child_gedcom_id OR sf_gc.wife_gedcom_id = fc_c.child_gedcom_id\n  JOIN genealogy.silver_family_child fc_gc ON fc_gc.family_gedcom_id = sf_gc.family_gedcom_id\n),\n\nrelatives_named AS (\n  SELECT DISTINCT r.file_id, r.year, r.relation, r.relative_id,\n    COALESCE(pl.given_name, '') AS given_name, COALESCE(pl.surname, '') AS surname,\n    pl.birth_year, pl.death_year\n  FROM relatives r\n  JOIN genealogy.gold_person_life pl ON pl.person_gedcom_id = r.relative_id\n  WHERE r.relative_id IS NOT NULL AND r.relative_id != r.primary_person_id\n),\n\ncandidate_names AS (\n  SELECT file_id, year, relation, relative_id, birth_year, death_year,\n    COALESCE((SELECT MAX(ab.full_name) FROM genealogy.ref_forename_abbreviation ab WHERE ab.abbr = UPPER(TRIM(REGEXP_EXTRACT(given_name, '^(\\\\S+)', 1)))), UPPER(TRIM(REGEXP_EXTRACT(given_name, '^(\\\\S+)', 1)))) AS forename_first, UPPER(TRIM(surname)) AS surname\n  FROM relatives_named\n  WHERE surname != ''\n\n  UNION ALL\n\n  SELECT rn.file_id, rn.year, rn.relation, rn.relative_id, rn.birth_year, rn.death_year,\n    COALESCE((SELECT MAX(ab.full_name) FROM genealogy.ref_forename_abbreviation ab WHERE ab.abbr = UPPER(TRIM(REGEXP_EXTRACT(a.alias_given_name, '^(\\\\S+)', 1)))), UPPER(TRIM(REGEXP_EXTRACT(a.alias_given_name, '^(\\\\S+)', 1)))) AS forename_first, UPPER(TRIM(a.alias_surname)) AS surname\n  FROM relatives_named rn\n  JOIN genealogy.silver_person_alias a ON a.person_gedcom_id = rn.relative_id\n  WHERE a.alias_surname IS NOT NULL AND a.alias_surname != ''\n),\n\n-- Name match AND the census age gate: a head's age must put them within 5 years of the\n-- relative's tree birth year. Without an age that fits, no link.\ncandidate_matches AS (\n  SELECT DISTINCT c.file_id, c.relation, c.relative_id, c.birth_year,\n    m.page_index, m.person_index, m.name_raw\n  FROM candidate_names c\n  JOIN mentions m\n    ON m.file_id = c.file_id\n   AND m.forename_first = c.forename_first\n   AND m.surname_last = c.surname\n  WHERE c.birth_year IS NOT NULL\n    AND c.birth_year <= TRY_CAST(SUBSTR(c.year, 1, 4) AS INT)\n    AND (c.death_year IS NULL OR c.death_year >= TRY_CAST(SUBSTR(c.year, 1, 4) AS INT))\n    AND ABS(TRY_CAST(SUBSTR(c.year, 1, 4) AS INT) - m.age_years - c.birth_year) <= 5\n    -- relative not already linked in this file\n    AND NOT EXISTS (\n      SELECT 1 FROM genealogy.silver_document_person o\n      WHERE o.file_id = c.file_id AND o.person_gedcom_id = c.relative_id\n    )\n),\n\n-- One mention for one relative, no guessing: skip anything ambiguous either way.\n-- (CONCAT_WS, not CONCAT: page_index is NULL on most mentions and CONCAT would return NULL.)\nmention_counts AS (\n  SELECT file_id, page_index, person_index, COUNT(DISTINCT relative_id) AS n_relatives\n  FROM candidate_matches GROUP BY file_id, page_index, person_index\n),\nrelative_counts AS (\n  SELECT file_id, relative_id, COUNT(DISTINCT CONCAT_WS('|', CAST(page_index AS STRING), CAST(person_index AS STRING))) AS n_mentions\n  FROM candidate_matches GROUP BY file_id, relative_id\n),\nfinal AS (\n  SELECT cm.file_id, cm.relative_id, cm.relation, cm.page_index, cm.person_index\n  FROM candidate_matches cm\n  JOIN mention_counts mc ON mc.file_id = cm.file_id AND mc.page_index <=> cm.page_index AND mc.person_index = cm.person_index\n  JOIN relative_counts rc ON rc.file_id = cm.file_id AND rc.relative_id = cm.relative_id\n  WHERE mc.n_relatives = 1 AND rc.n_mentions = 1\n)\n\nSELECT\n  f.file_id,\n  md.file_name,\n  f.relative_id AS person_gedcom_id,\n  pl.given_name || ' ' || pl.surname AS display_name,\n  'HOUSEHOLD_INFERENCE_V2' AS match_method,\n  'MEDIUM' AS match_confidence,\n  1 AS candidate_count,\n  CONCAT('Head of own household (', f.relation, ' of the primary) matched via silver_transcript_person_mention') AS notes,\n  CURRENT_TIMESTAMP(),\n  f.page_index,\n  f.person_index\nFROM final f\nJOIN (SELECT DISTINCT file_id, file_name FROM matched_docs) md ON md.file_id = f.file_id\nJOIN genealogy.gold_person_life pl ON pl.person_gedcom_id = f.relative_id\nWHERE NOT EXISTS (\n  SELECT 1 FROM genealogy.silver_document_person sdp\n  WHERE sdp.file_id = f.file_id AND sdp.person_gedcom_id = f.relative_id\n)"}
import json
res = {}
for name, sql in CELLS.items():
    t0 = time.time()
    plan = spark.sql("EXPLAIN FORMATTED " + sql).collect()[0][0]
    t1 = time.time()
    n = spark.sql(sql).count()
    t2 = time.time()
    res[name] = {"plan_s": round(t1 - t0, 1), "run_s": round(t2 - t1, 1), "rows": n, "plan_chars": len(plan)}
    print(name, res[name])
dbutils.notebook.exit(json.dumps(res))
